import Root from "./1Adding Interactivity/5UpdatingArrays"
import Sub from "./subReLearn"
import "./ReLearn.css"
import { useState } from "react"

export default function () {
  return (
    <>
    <Root/>
    </>
  );
}

let id = 0
export function Screen() {
  const [val,setVal] = useState()
  const [arr, setArr] = useState([])
  const [remove, setRemove] = useState(0)
  return (
    <>
    <input onChange={(e) => {setVal(e.target.value)}}/>
    <input type="submit" onClick={() => {setArr([...arr,{value: val, id: id++}])}}/> <br/>
    <input onChange={(e) => {setRemove(e.target.value)}}/>
    <input type="submit" value="remove" onClick={() => {setArr(arr.filter(e => e.id!=remove))}}/>
    <p>{arr.map(e => <>{e.value} {e.id}<br/></>)}</p>
    </>
  );
}



// http://localhost:3000
